package loom

import loom.report.TbGen
import org.scalatest.flatspec.AnyFlatSpec
import org.scalatest.matchers.should.Matchers

class TbGenSpec extends AnyFlatSpec with Matchers {
  private val sample =
    """// Generated by CIRCT firtool
      |module LmDemoTop(	// src/loom/scala/main/loom/rtl/LmDemo.scala:10:7
      |  input          clock,	// src/x.scala:10
      |                 reset,	// src/x.scala:10
      |  output         io_master_0_ready,	// src/x.scala:11
      |  input          io_master_0_valid,	// src/x.scala:11
      |                 io_master_0_bits_write,	// src/x.scala:11
      |  input  [31:0]  io_master_0_bits_addr,	// src/x.scala:11
      |  output [2:0]   io_perf_returnSlots_0,	// src/x.scala:12
      |                 io_perf_returnSlots_1	// src/x.scala:12
      |);
      |
      |  assign io_master_0_ready = 1'h0;
      |endmodule
      |""".stripMargin

  "TbGen" should "parse directions, widths and continuation lines" in {
    val ports = TbGen.parsePorts(sample, "LmDemoTop")
    ports.map(_.name) shouldBe Seq(
      "clock", "reset", "io_master_0_ready", "io_master_0_valid",
      "io_master_0_bits_write", "io_master_0_bits_addr",
      "io_perf_returnSlots_0", "io_perf_returnSlots_1")
    ports.find(_.name == "io_master_0_bits_addr").get.width shouldBe 32
    ports.find(_.name == "io_master_0_bits_write").get.width shouldBe 1
    ports.find(_.name == "io_perf_returnSlots_0").get.isInput shouldBe false
    ports.find(_.name == "io_perf_returnSlots_1").get.isInput shouldBe false
    ports.find(_.name == "io_perf_returnSlots_1").get.width shouldBe 3
  }

  it should "not carry a width across a new direction" in {
    val text =
      """module M(
        |  output [7:0] a,
        |  input        b,
        |               c
        |);
        |endmodule
        |""".stripMargin
    val ports = TbGen.parsePorts(text, "M")
    ports.find(_.name == "b").get.width shouldBe 1
    ports.find(_.name == "c").get.width shouldBe 1
  }

  it should "generate a compilable skeleton with zeroed inputs" in {
    val tb = TbGen.testbench("LmDemoTop", sample)
    tb should include("module LmDemoTop_tb;")
    tb should include("logic [31:0] io_master_0_bits_addr;")
    tb should include(".io_master_0_bits_addr(io_master_0_bits_addr)")
    tb should include("io_master_0_valid = '0;")
    tb should include("io_master_0_bits_addr = '0;")
    tb should not include "io_master_0_ready = '0;"
    tb should not include "io_perf_returnSlots_0 = '0;"
    tb should include("$finish;")
    TbGen.testbench("LmDemoTop", sample) shouldBe tb
  }
}
